<?php
namespace Tests\Feature;
use App\Models\DeliveryAddress;
use App\Models\FoodOrder;
use App\Models\MenuCategory;
use App\Models\MenuItem;
use App\Models\Promotion;
use App\Models\Restaurant;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;
class FoodDeliveryTest extends TestCase {
 use RefreshDatabase;
 protected function setUp():void{parent::setUp();$this->withoutVite();}
 private function restaurant(array $attrs=[]):array{$owner=User::factory()->create();$owner->forceFill(['role'=>'restaurant'])->save();$restaurant=Restaurant::create($attrs+['owner_id'=>$owner->id,'name'=>'Good Food','slug'=>'good-food','delivery_fee_cents'=>300]);$category=MenuCategory::create(['restaurant_id'=>$restaurant->id,'name'=>'Meals']);$item=MenuItem::create(['restaurant_id'=>$restaurant->id,'menu_category_id'=>$category->id,'name'=>'Rice bowl','price_cents'=>1250,'stock'=>5,'available'=>true]);return compact('owner','restaurant','category','item');}
 private function address(User $user):DeliveryAddress{return DeliveryAddress::create(['user_id'=>$user->id,'recipient_name'=>'Test Customer','phone'=>'555-0100','address_line'=>'1 Test Lane','city'=>'Test City']);}
 public function test_storefront_shows_open_restaurants_and_menu():void{$data=$this->restaurant();$this->get('/')->assertOk()->assertSee('Good Food');$this->get(route('food.restaurant',$data['restaurant']))->assertOk()->assertSee('Rice bowl');}
 public function test_guest_cannot_add_cart_or_checkout():void{$data=$this->restaurant();$this->post(route('food.cart.add',[$data['restaurant'],$data['item']]),['quantity'=>1])->assertRedirect(route('login'));$this->post(route('food.checkout'))->assertRedirect(route('login'));}
 public function test_checkout_reprices_cart_saves_snapshots_and_consumes_promotion_and_stock():void{$data=$this->restaurant();$customer=User::factory()->create();$address=$this->address($customer);$promotion=Promotion::create(['code'=>'SAVE10','discount_percent'=>10,'minimum_subtotal_cents'=>1000,'max_uses'=>1,'active'=>true]);$this->actingAs($customer)->withSession(['cart'=>['restaurant_id'=>$data['restaurant']->id,'items'=>[$data['item']->id=>2]]])->post(route('food.checkout'),['address_id'=>$address->id,'promotion_code'=>'save10'])->assertRedirect();$order=FoodOrder::with('items')->firstOrFail();$this->assertSame(2500,$order->subtotal_cents);$this->assertSame(250,$order->discount_cents);$this->assertSame(2550,$order->total_cents);$this->assertSame('unpaid',$order->payment_status);$this->assertSame('Test City',$order->address_snapshot['city']);$this->assertSame('Rice bowl',$order->items[0]->item_name);$this->assertSame(3,$data['item']->fresh()->stock);$this->assertSame(1,$promotion->fresh()->uses);$this->assertSame(1,$order->events()->count());}
 public function test_checkout_rejects_another_users_address():void{$data=$this->restaurant();$customer=User::factory()->create();$address=$this->address(User::factory()->create());$this->actingAs($customer)->withSession(['cart'=>['restaurant_id'=>$data['restaurant']->id,'items'=>[$data['item']->id=>1]]])->post(route('food.checkout'),['address_id'=>$address->id])->assertNotFound();$this->assertSame(0,FoodOrder::count());}
 public function test_checkout_rejects_out_of_stock_without_creating_order():void{$data=$this->restaurant();$customer=User::factory()->create();$address=$this->address($customer);$this->actingAs($customer)->withSession(['cart'=>['restaurant_id'=>$data['restaurant']->id,'items'=>[$data['item']->id=>6]]])->post(route('food.checkout'),['address_id'=>$address->id])->assertSessionHasErrors('items');$this->assertSame(0,FoodOrder::count());$this->assertSame(5,$data['item']->fresh()->stock);}
 public function test_customer_cannot_change_order_status():void{$data=$this->restaurant();$customer=User::factory()->create();$order=FoodOrder::create(['reference'=>'FD-TEST-1','customer_id'=>$customer->id,'restaurant_id'=>$data['restaurant']->id,'address_snapshot'=>[],'subtotal_cents'=>1250,'delivery_fee_cents'=>300,'discount_cents'=>0,'total_cents'=>1550]);$this->actingAs($customer)->patch(route('food.orders.transition',$order->id),['status'=>'accepted'])->assertForbidden();$this->assertSame('pending',$order->fresh()->status);}
 public function test_driver_can_only_deliver_assigned_order_and_marks_cash_paid_on_delivery():void{$data=$this->restaurant();$customer=User::factory()->create();$driver=User::factory()->create();$driver->forceFill(['role'=>'delivery'])->save();$order=FoodOrder::create(['reference'=>'FD-TEST-2','customer_id'=>$customer->id,'restaurant_id'=>$data['restaurant']->id,'delivery_staff_id'=>$driver->id,'address_snapshot'=>[],'subtotal_cents'=>1250,'delivery_fee_cents'=>300,'discount_cents'=>0,'total_cents'=>1550,'status'=>'ready']);$this->actingAs($driver)->patch(route('food.orders.transition',$order->id),['status'=>'picked_up'])->assertRedirect();$this->patch(route('food.orders.transition',$order->id),['status'=>'delivered'])->assertRedirect();$this->assertSame('paid',$order->fresh()->payment_status);$other=User::factory()->create();$other->forceFill(['role'=>'delivery'])->save();$this->actingAs($other)->patch(route('food.orders.transition',$order->id),['status'=>'delivered'])->assertForbidden();}
 public function test_customer_registration_cannot_assign_privileged_role():void{$this->post(route('register'),['name'=>'New Customer','email'=>'new@example.test','password'=>'password','password_confirmation'=>'password','role'=>'admin'])->assertRedirect();$this->assertSame('customer',User::where('email','new@example.test')->firstOrFail()->role);}
 public function test_restaurant_owner_cannot_edit_another_restaurants_menu():void{$one=$this->restaurant();$two=$this->restaurant(['name'=>'Other','slug'=>'other']);$this->actingAs($one['owner'])->post(route('food.categories.store',$two['restaurant']),['name'=>'Stolen'])->assertNotFound();$this->assertSame(1,$two['restaurant']->categories()->count());}
 public function test_restaurant_owner_cannot_advance_order_from_invalid_state_and_can_reject_with_stock_restored():void{$data=$this->restaurant();$customer=User::factory()->create();$order=FoodOrder::create(['reference'=>'FD-TEST-3','customer_id'=>$customer->id,'restaurant_id'=>$data['restaurant']->id,'address_snapshot'=>[],'subtotal_cents'=>1250,'delivery_fee_cents'=>300,'discount_cents'=>0,'total_cents'=>1550,'status'=>'pending']);$order->items()->create(['menu_item_id'=>$data['item']->id,'item_name'=>'Rice bowl','unit_price_cents'=>1250,'quantity'=>2,'line_total_cents'=>2500]);$this->actingAs($data['owner'])->patch(route('food.orders.transition',$order->id),['status'=>'ready'])->assertForbidden();$this->patch(route('food.orders.transition',$order->id),['status'=>'rejected'])->assertRedirect();$this->assertSame(7,$data['item']->fresh()->stock);$this->assertSame('rejected',$order->fresh()->status);}
 public function test_restaurant_cannot_apply_another_restaurants_category_to_a_menu_item():void{$one=$this->restaurant();$two=$this->restaurant(['name'=>'Other','slug'=>'other']);$this->actingAs($one['owner'])->post(route('food.items.store',$one['restaurant']),['menu_category_id'=>$two['category']->id,'name'=>'Unsafe item','price_cents'=>100])->assertSessionHasErrors('menu_category_id');$this->assertSame(1,$one['restaurant']->items()->count());}
 public function test_addresses_are_editable_and_scoped_to_the_customer():void{$owner=User::factory()->create();$address=$this->address($owner);$other=User::factory()->create();$data=['recipient_name'=>'New Name','phone'=>'555-0101','address_line'=>'2 New Lane','city'=>'New City'];$this->actingAs($other)->patch(route('food.addresses.update',$address->id),$data)->assertNotFound();$this->actingAs($owner)->patch(route('food.addresses.update',$address->id),$data)->assertRedirect();$this->assertSame('New City',$address->fresh()->city);$this->delete(route('food.addresses.delete',$address->id))->assertRedirect();$this->assertDatabaseMissing('delivery_addresses',['id'=>$address->id]);}
 public function test_dashboard_does_not_expose_orders_to_customers():void{$customer=User::factory()->create();$this->actingAs($customer)->get(route('food.restaurant.dashboard'))->assertForbidden();}
}
